import { Btn } from "@/registry/p1/internal/btn";
import { Icon } from "@/registry/p1/internal/icons";
import "./feature-media.css";

export interface FeatureMediaBullet {
  text: string;
}
export interface FeatureMediaProps {
  eyebrow: string;
  title: string;
  body: string;
  bullets: FeatureMediaBullet[];
  buttonLabel: string;
  imageSrc: string;
  mediaSide: "right" | "left";
  tone: "white" | "light" | "dark";
}

export function FeatureMediaRender({
  eyebrow,
  title,
  body,
  bullets,
  buttonLabel,
  imageSrc,
  mediaSide,
  tone,
}: FeatureMediaProps) {
  const list = bullets || [];
  return (
    <div className="p1-feature-media p1-block" data-tone={tone} data-mediaside={mediaSide}>
      <div className="p1-feature-media__inner">
        <div className="p1-feature-media__media">
          <div className="p1-feature-media__img-frame">
            {imageSrc && <img src={imageSrc} alt="" className="p1-feature-media__img" />}
          </div>
        </div>
        <div className="p1-feature-media__copy">
          {eyebrow && <div className="p1-feature-media__eyebrow">{eyebrow}</div>}
          <h2 className="p1-feature-media__title">{title}</h2>
          <p className="p1-feature-media__body">{body}</p>
          {list.length > 0 && (
            <ul className="p1-feature-media__bullets">
              {list.map((b, i) => (
                <li key={i} className="p1-feature-media__bullet">
                  <span className="p1-feature-media__check" aria-hidden="true">
                    <Icon name="check" strokeWidth={2.4} className="p1-feature-media__check-icon" />
                  </span>
                  {b.text}
                </li>
              ))}
            </ul>
          )}
          {buttonLabel && (
            <Btn variant={tone === "dark" ? "yellow" : "primary"}>{buttonLabel}</Btn>
          )}
        </div>
      </div>
    </div>
  );
}

import type { ComponentConfig } from "@puckeditor/core";
import { defineMeta, wireframe } from '../define-meta';
import { FeatureMediaRender, type FeatureMediaProps, type FeatureMediaBullet } from "./feature-media";
export type { FeatureMediaProps, FeatureMediaBullet };

export const FeatureMediaBlock: ComponentConfig<FeatureMediaProps> = {
  fields: {
    eyebrow: {
      type: "text" as const,
      contentEditable: true,
      visible: false,
      ai: { instructions: "Short label above the heading. 2–4 words. E.g. How it works." },
    },
    title: {
      type: "text" as const,
      contentEditable: true,
      visible: false,
      ai: { instructions: "Section heading. Punchy claim, under 10 words." },
    },
    body: {
      type: "text" as const,
      contentEditable: true,
      visible: false,
      ai: { instructions: "1–2 sentence description supporting the heading." },
    },
    bullets: {
      type: "array" as const,
      arrayFields: {
        text: {
          type: "text" as const,
          contentEditable: true,
          visible: false,
          ai: { instructions: "One benefit, 4–8 words." },
        },
      },
      defaultItemProps: { text: "Benefit" },
      getItemSummary: (item: FeatureMediaBullet) => item.text || "Bullet",
    },
    buttonLabel: {
      type: "text" as const,
      contentEditable: true,
      visible: false,
      ai: { instructions: "CTA label. 3–6 words. E.g. See how it works →" },
    },
    imageSrc: {
      type: "text" as const,
      ai: { exclude: true },
    },
    mediaSide: {
      type: "radio" as const,
      options: [
        { label: "Right", value: "right" },
        { label: "Left", value: "left" },
      ],
    },
    tone: {
      type: "select" as const,
      options: [
        { label: "White", value: "white" },
        { label: "Light", value: "light" },
        { label: "Dark", value: "dark" },
      ],
    },
  },
  defaultProps: {
    eyebrow: "How it works",
    title: "Designed around the way you work.",
    body: "Move from idea to published in a few clicks. Preview every change, then make it live whenever you're ready.",
    bullets: [
      { text: "Visual, on-brand editing" },
      { text: "Preview before you publish" },
      { text: "Publish in one click" },
    ],
    buttonLabel: "See how it works →",
    imageSrc: wireframe(1000, 563),
    mediaSide: "right",
    tone: "white",
  },
  render: FeatureMediaRender,
};

export const meta = defineMeta({
  title: 'Feature Media',
  description: 'Side-by-side text+image block with eyebrow, title, body, bullet points, and a CTA button; use for product feature highlights.',
  categories: ["value"],
  published: true,
  registryDependencies: ["@p1/tokens","@p1/internal-btn","@p1/internal-icons"],
});

.p1-feature-media[data-tone="light"] { background-color: var(--p1-surface-subtle); }
.p1-feature-media[data-tone="dark"] {
  background-color: var(--p1-surface-inverse);
  color: var(--p1-fg-inverse);
}

.p1-feature-media__inner {
  align-items: center;
  display: grid;
  gap: var(--p1-space-xl);
  margin-inline: auto;
  max-inline-size: var(--p1-container-wide);
}
@media (width >= 48rem) {
  .p1-feature-media__inner { grid-template-columns: 1fr 1fr; }
  /* media on right (default): copy | media */
  .p1-feature-media[data-mediaside="right"] .p1-feature-media__copy { order: 1; }
  .p1-feature-media[data-mediaside="right"] .p1-feature-media__media { order: 2; }
  /* media on left: media | copy */
  .p1-feature-media[data-mediaside="left"] .p1-feature-media__media { order: 1; }
  .p1-feature-media[data-mediaside="left"] .p1-feature-media__copy { order: 2; }
}

.p1-feature-media__img-frame {
  aspect-ratio: 4 / 3;
  background-color: color-mix(in oklch, var(--p1-surface-inverse) 8%, transparent);
  border-radius: var(--p1-radius-xl);
  overflow: hidden;
}
.p1-feature-media[data-tone="dark"] .p1-feature-media__img-frame {
  border: 1px solid var(--p1-border-inverse);
}
.p1-feature-media:not([data-tone="dark"]) .p1-feature-media__img-frame {
  border: 1px solid var(--p1-border);
}

.p1-feature-media__img { block-size: 100%; inline-size: 100%; object-fit: cover; }

.p1-feature-media__eyebrow {
  color: var(--p1-accent);
  font-size: var(--p1-text-sm);
  font-weight: var(--p1-weight-bold);
  letter-spacing: 0.14em;
  margin-block-end: var(--p1-space-sm);
  text-transform: uppercase;
}
.p1-feature-media[data-tone="dark"] .p1-feature-media__eyebrow { color: var(--p1-warning); }

.p1-feature-media__title {
  font-size: var(--p1-text-2xl);
  font-weight: var(--p1-weight-bold);
  letter-spacing: -0.02em;
  line-height: var(--p1-leading-tight);
  margin-block-end: var(--p1-space-sm);
  text-wrap: balance;
}
@media (width >= 48rem) {
  .p1-feature-media__title { font-size: var(--p1-text-3xl); }
}

.p1-feature-media__body {
  color: var(--p1-fg-muted);
  font-size: var(--p1-text-lg);
  line-height: var(--p1-leading-normal);
  margin-block-end: var(--p1-space-md);
}
.p1-feature-media[data-tone="dark"] .p1-feature-media__body { color: var(--p1-fg-inverse-subtle); }

.p1-feature-media__bullets {
  display: flex;
  flex-direction: column;
  gap: var(--p1-space-sm);
  list-style: none;
  margin-block-end: var(--p1-space-lg);
  padding: 0;
}
.p1-feature-media__bullet {
  align-items: center;
  display: flex;
  font-weight: var(--p1-weight-medium);
  gap: var(--p1-space-sm);
}
.p1-feature-media__check {
  align-items: center;
  background-color: color-mix(in oklch, var(--p1-success) 10%, transparent);
  block-size: 1.375rem;
  border-radius: var(--p1-radius-pill);
  color: var(--p1-success);
  display: grid;
  flex: none;
  inline-size: 1.375rem;
  justify-items: center;
  place-content: center;
}
.p1-feature-media[data-tone="dark"] .p1-feature-media__check {
  background-color: color-mix(in oklch, var(--p1-warning) 20%, transparent);
  color: var(--p1-warning);
}
.p1-feature-media__check-icon { block-size: 0.875rem; inline-size: 0.875rem; }

